class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in self.tickers
        }

        self.spy_closes = deque(maxlen=100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.previous_closes = {ticker: None for ticker in self.tickers}
        self.aapl_red_streak = 0

        self.previous_spy_above_sma = None
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities continue to consume every available daily bar,
        # even when one missing subscription forces all trading rules to be skipped.
        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].Close))

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            previous_aapl_close = self.previous_closes["AAPL"]
            if previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.Update(bars["AAPL"].EndTime, aapl_close)

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = float(bar.Close)

        spy_above_sma = None
        if "SPY" in bars and len(self.spy_closes) == 100:
            spy_close = float(bars["SPY"].Close)
            spy_sma = sum(self.spy_closes) / 100.0
            spy_above_sma = spy_close > spy_sma

        if len(bars) != len(self.symbols):
            if spy_above_sma is not None:
                self.previous_spy_above_sma = spy_above_sma
            return

        spy_close = float(bars["SPY"].Close)

        # Sells are evaluated before buys.
        if (
            self.strategy_a_shares > 0
            and self.previous_spy_above_sma is True
            and spy_above_sma is False
        ):
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if (
            self.strategy_b_shares > 0
            and self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60.0
        ):
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if (
            self.strategy_a_shares == 0
            and self.previous_spy_above_sma is False
            and spy_above_sma is True
        ):
            quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

        if (
            self.strategy_b_shares == 0
            and self.aapl_rsi.IsReady
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20_000.0
        ):
            quantity = floor(20_000.0 / float(bars["AAPL"].Close))
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.strategy_b_shares = quantity

        if spy_above_sma is not None:
            self.previous_spy_above_sma = spy_above_sma

