        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0
        self.last_updates = {}

    def OnData(self, data: Slice):
        bars = data.Bars

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if spy in bars and self.last_updates.get(spy) != bars[spy].EndTime:
            self.spy_closes.appendleft(Decimal(str(bars[spy].Close)))
            self.last_updates[spy] = bars[spy].EndTime

        if aapl in bars and self.last_updates.get(aapl) != bars[aapl].EndTime:
            aapl_close = Decimal(str(bars[aapl].Close))
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(bars[aapl].EndTime, aapl_close)
            self.last_updates[aapl] = bars[aapl].EndTime

        if any(symbol not in bars for symbol in self.symbols.values()):
            return

        if len(self.spy_closes) < 101 or not self.aapl_rsi.IsReady:
            return

        spy_close = self.spy_closes[0]
        previous_spy_close = self.spy_closes[1]
        current_spy_sma = sum(list(self.spy_closes)[:100]) / Decimal(100)
        previous_spy_sma = sum(list(self.spy_closes)[1:101]) / Decimal(100)

        upward_cross = (
            previous_spy_close <= previous_spy_sma and spy_close > current_spy_sma
        )
        downward_cross = (
            previous_spy_close >= previous_spy_sma and spy_close < current_spy_sma
        )

        # Both independent slots evaluate their sells before either slot evaluates buys.
        if self.strategy_a_quantity > 0 and downward_cross:
            self.MarketOrder(spy, -self.strategy_a_quantity)
            self.strategy_a_quantity = 0

        if self.strategy_b_quantity > 0 and self.aapl_rsi.Current.Value > Decimal(60):
            self.MarketOrder(aapl, -self.strategy_b_quantity)
            self.strategy_b_quantity = 0

        if self.strategy_a_quantity == 0 and upward_cross:
            target_value = Decimal("0.40") * self.Portfolio.TotalPortfolioValue
            quantity = floor(target_value / spy_close)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.strategy_a_quantity = quantity

        if self.strategy_b_quantity == 0 and self.aapl_red_streak >= 3:
            allocation = Decimal(20_000)
            if self.Portfolio.Cash >= allocation:
                quantity = floor(allocation / Decimal(str(bars[aapl].Close)))
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.strategy_b_quantity = quantity

