class ParallelDailyStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.previous_spy_relation = None

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False
        self.order_strategies = {}

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_bar = data.Bars[spy] if data.Bars.ContainsKey(spy) else None
        aapl_bar = data.Bars[aapl] if data.Bars.ContainsKey(aapl) else None

        upward_cross = False
        downward_cross = False
        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            if self.spy_sma.IsReady:
                relation = spy_bar.Close - self.spy_sma.Current.Value
                if self.previous_spy_relation is not None:
                    upward_cross = self.previous_spy_relation <= 0 and relation > 0
                    downward_cross = self.previous_spy_relation >= 0 and relation < 0
                self.previous_spy_relation = relation

        if aapl_bar is not None:
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.Close

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        # Each ticker belongs to exactly one strategy, so this also incorporates
        # any quantity changes made by LEAN for corporate actions.
        if not self.spy_order_pending and self.spy_lot:
            self.spy_lot = max(0, int(self.Portfolio[spy].Quantity))
        if not self.aapl_order_pending and self.aapl_lot:
            self.aapl_lot = max(0, int(self.Portfolio[aapl].Quantity))

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and not self.spy_order_pending and downward_cross:
            self._submit_order("spy", spy, -self.spy_lot)

        if (self.aapl_lot > 0 and not self.aapl_order_pending
                and self.aapl_rsi.IsReady
                and self.aapl_rsi.Current.Value > 60):
            self._submit_order("aapl", aapl, -self.aapl_lot)

        if self.spy_lot == 0 and not self.spy_order_pending and upward_cross:
            quantity = self.CalculateOrderQuantity(spy, 0.40)
            if quantity > 0:
                self._submit_order("spy", spy, quantity)

        if (self.aapl_lot == 0 and not self.aapl_order_pending
                and self.aapl_rsi.IsReady and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000):
            quantity = math.floor(20_000 / aapl_bar.Close)
            if quantity > 0:
                self._submit_order("aapl", aapl, quantity)

    def _submit_order(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity)
        self.order_strategies[ticket.OrderId] = strategy
        if strategy == "spy":
            self.spy_order_pending = True
        else:
            self.aapl_order_pending = True

    def OnOrderEvent(self, order_event):
        strategy = self.order_strategies.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.FillQuantity != 0:
            if strategy == "spy":
                self.spy_lot = max(0, self.spy_lot + int(order_event.FillQuantity))
            else:
                self.aapl_lot = max(0, self.aapl_lot + int(order_event.FillQuantity))

        if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            if strategy == "spy":
                self.spy_order_pending = False
            else:
                self.aapl_order_pending = False
            del self.order_strategies[order_event.OrderId]

