class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.closes = {
            ticker: deque(maxlen=101) for ticker in self.symbols
        }
        self.red_streak = {ticker: 0 for ticker in self.symbols}

        self.rsi_period = 14
        self.aapl_changes = 0
        self.aapl_average_gain = 0.0
        self.aapl_average_loss = 0.0
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        for ticker, bar in bars.items():
            history = self.closes[ticker]
            if history:
                if bar.close < history[-1]:
                    self.red_streak[ticker] += 1
                else:
                    self.red_streak[ticker] = 0

                if ticker == "AAPL":
                    self._update_aapl_rsi(float(bar.close - history[-1]))
            history.append(float(bar.close))

        if len(bars) != len(self.symbols) or self.is_warming_up:
            return

        if len(self.closes["SPY"]) < 101 or self.aapl_rsi is None:
            return

        spy_history = self.closes["SPY"]
        previous_sma = sum(list(spy_history)[:-1]) / 100.0
        current_sma = sum(list(spy_history)[-100:]) / 100.0
        previous_close = spy_history[-2]
        current_close = spy_history[-1]

        upward_cross = previous_close <= previous_sma and current_close > current_sma
        downward_cross = previous_close >= previous_sma and current_close < current_sma

        # Both independent slots evaluate their sells before either slot's buy.
        if self.strategy_a_shares > 0 and downward_cross:
            self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi > 60.0:
            self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and upward_cross:
            quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.red_streak["AAPL"] >= 3:
            if self.portfolio.cash >= 20_000:
                quantity = floor(20_000 / bars["AAPL"].close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.strategy_b_shares = quantity

    def _update_aapl_rsi(self, change):
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.aapl_changes < self.rsi_period:
            self.aapl_average_gain += gain
            self.aapl_average_loss += loss
            self.aapl_changes += 1
            if self.aapl_changes == self.rsi_period:
                self.aapl_average_gain /= self.rsi_period
                self.aapl_average_loss /= self.rsi_period
                self._set_aapl_rsi()
            return

        self.aapl_average_gain = (
            self.aapl_average_gain * (self.rsi_period - 1) + gain
        ) / self.rsi_period
        self.aapl_average_loss = (
            self.aapl_average_loss * (self.rsi_period - 1) + loss
        ) / self.rsi_period
        self._set_aapl_rsi()

    def _set_aapl_rsi(self):
        if self.aapl_average_loss == 0:
            self.aapl_rsi = 100.0 if self.aapl_average_gain > 0 else 50.0
            return
        relative_strength = self.aapl_average_gain / self.aapl_average_loss
        self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)

