                if split.Type == SplitType.SplitOccurred:
                    lot = getattr(self, lot_name)
                    if lot > 0:
                        setattr(
                            self,
                            lot_name,
                            int(round(lot / float(split.SplitFactor))),
                        )

        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_crossed_up = False
        spy_crossed_down = False

        if "SPY" in bars:
            spy_close = bars["SPY"].Close
            self.spy_sma.Update(bars["SPY"].EndTime, spy_close)
            if self.spy_sma.IsReady:
                spy_above_sma = spy_close > self.spy_sma.Current.Value
                if self.previous_spy_above_sma is not None:
                    spy_crossed_up = (
                        spy_above_sma and not self.previous_spy_above_sma
                    )
                    spy_crossed_down = (
                        not spy_above_sma and self.previous_spy_above_sma
                    )
                self.previous_spy_above_sma = spy_above_sma

        if "AAPL" in bars:
            aapl_close = bars["AAPL"].Close
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is not None:
                if aapl_close < previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(bars["AAPL"].EndTime, aapl_close)

        # Price and indicator state advances whenever its bar exists, even when
        # another subscription is missing and today's rules must be skipped.
        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.Close

        if len(bars) != len(self.symbols):
            return

        # Evaluate sells before buys.
        if self.spy_lot > 0 and self.spy_sma.IsReady and spy_crossed_down:
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        ):
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and self.spy_sma.IsReady and spy_crossed_up:
            quantity = int(
                (0.40 * float(self.Portfolio.TotalPortfolioValue))
                / float(bars["SPY"].Close)
            )
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if (
            self.aapl_lot == 0
            and self.aapl_rsi.IsReady
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
        ):
            quantity = int(20_000 // float(bars["AAPL"].Close))
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

