class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_previous_difference = None
        self.spy_cross_ready = False
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        # Each strategy owns and closes only its own lot.
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Keep market-state quantities current even on a day on which another
        # subscribed ticker is missing and rule evaluation must be skipped.
        upward_cross = False
        downward_cross = False
        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            if self.spy_sma.IsReady:
                current_difference = spy_bar.Close - self.spy_sma.Current.Value
                if self.spy_previous_difference is not None:
                    self.spy_cross_ready = True
                    upward_cross = (
                        current_difference > 0 and self.spy_previous_difference <= 0
                    )
                    downward_cross = (
                        current_difference < 0 and self.spy_previous_difference >= 0
                    )
                self.spy_previous_difference = current_difference

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_bar.Close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        # No strategy may trade until every indicator needed by the system is
        # formed and the SMA has a fully formed prior-day relation for a cross.
        if (
            not self.spy_sma.IsReady
            or not self.spy_cross_ready
            or not self.aapl_rsi.IsReady
        ):
            return

        # Evaluate every eligible sell before evaluating any eligible buy.
        if self.spy_lot > 0:
            if downward_cross:
                self.MarketOrder(spy, -self.spy_lot)
                self.spy_lot = 0

        if self.aapl_lot > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(aapl, -self.aapl_lot)
                self.aapl_lot = 0

        # Buy reasons are evaluated only for lots which are now empty.
        if self.spy_lot == 0 and upward_cross:
            quantity = self.CalculateOrderQuantity(spy, 0.40)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if self.Portfolio.Cash >= cash_to_invest:
                quantity = int(cash_to_invest // data.Bars[aapl].Close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.aapl_lot = quantity

