class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_difference = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi_previous_close = None
        self.aapl_rsi_change_count = 0
        self.aapl_rsi_initial_gains = 0.0
        self.aapl_rsi_initial_losses = 0.0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = data.Bars
        all_bars_present = all(bars.ContainsKey(symbol) for symbol in self.symbols.values())

        spy_bar = bars[self.symbols["SPY"]] if bars.ContainsKey(self.symbols["SPY"]) else None
        aapl_bar = bars[self.symbols["AAPL"]] if bars.ContainsKey(self.symbols["AAPL"]) else None

        upward_cross = False
        downward_cross = False

        if spy_bar is not None:
            spy_close = float(spy_bar.Close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 100:
                difference = spy_close - sum(self.spy_closes) / 100.0
                if self.spy_previous_difference is not None:
                    upward_cross = self.spy_previous_difference <= 0.0 and difference > 0.0
                    downward_cross = self.spy_previous_difference >= 0.0 and difference < 0.0
                self.spy_previous_difference = difference

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)

            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close

            if self.aapl_rsi_previous_close is not None:
                change = aapl_close - self.aapl_rsi_previous_close
                gain = max(change, 0.0)
                loss = max(-change, 0.0)
                self.aapl_rsi_change_count += 1

                if self.aapl_rsi_change_count <= 14:
                    self.aapl_rsi_initial_gains += gain
                    self.aapl_rsi_initial_losses += loss
                    if self.aapl_rsi_change_count == 14:
                        self.aapl_average_gain = self.aapl_rsi_initial_gains / 14.0
                        self.aapl_average_loss = self.aapl_rsi_initial_losses / 14.0
                else:
                    self.aapl_average_gain = (self.aapl_average_gain * 13.0 + gain) / 14.0
                    self.aapl_average_loss = (self.aapl_average_loss * 13.0 + loss) / 14.0

                if self.aapl_average_gain is not None:
                    if self.aapl_average_loss == 0.0:
                        self.aapl_rsi = 50.0 if self.aapl_average_gain == 0.0 else 100.0
                    else:
                        relative_strength = self.aapl_average_gain / self.aapl_average_loss
                        self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)

            self.aapl_rsi_previous_close = aapl_close

        if not all_bars_present:
            return

        if self.strategy_a_shares > 0 and downward_cross:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi is not None and self.aapl_rsi > 60.0:
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and upward_cross:
            shares = math.floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / float(spy_bar.Close))
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20000.0
            if float(self.Portfolio.Cash) >= cash_to_invest:
                shares = math.floor(cash_to_invest / float(aapl_bar.Close))
                if shares > 0:
                    self.MarketOrder(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares

