class IndependentDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in self.tickers
        }

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.previous_spy_difference = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.lots = {"A": 0, "B": 0}
        self.pending_orders = {"A": set(), "B": set()}
        self.order_strategies = {}

    def OnData(self, data):
        bars = {}
        for ticker in self.tickers:
            symbol = self.symbols[ticker]
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.Close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        current_spy_difference = None
        if spy_bar is not None and self.spy_sma.IsReady:
            current_spy_difference = spy_bar.Close - self.spy_sma.Current.Value

        if len(bars) == len(self.tickers):
            self._evaluate_sells()
            self._evaluate_buys(bars, current_spy_difference)

        if current_spy_difference is not None:
            self.previous_spy_difference = current_spy_difference

    def _evaluate_sells(self):
        if (
            self.lots["A"] > 0
            and not self.pending_orders["A"]
            and self.previous_spy_difference is not None
            and self.previous_spy_difference >= 0
            and self.spy_sma.Current.Value > self.Securities[self.symbols["SPY"]].Close
        ):
            self._submit_order("A", self.symbols["SPY"], -self.lots["A"], "Strategy A sell")

        if (
            self.lots["B"] > 0
            and not self.pending_orders["B"]
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        ):
            self._submit_order("B", self.symbols["AAPL"], -self.lots["B"], "Strategy B sell")

    def _evaluate_buys(self, bars, current_spy_difference):
        if (
            self.lots["A"] == 0
            and not self.pending_orders["A"]
            and self.previous_spy_difference is not None
            and current_spy_difference is not None
            and self.previous_spy_difference <= 0
            and current_spy_difference > 0
        ):
            quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) // bars["SPY"].Close)
            if quantity > 0:
                self._submit_order("A", self.symbols["SPY"], quantity, "Strategy A buy")

        if (
            self.lots["B"] == 0
            and not self.pending_orders["B"]
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
        ):
            quantity = int(20_000 // bars["AAPL"].Close)
            if quantity > 0:
                self._submit_order("B", self.symbols["AAPL"], quantity, "Strategy B buy")

    def _submit_order(self, strategy, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, False, tag)
        self.pending_orders[strategy].add(ticket.OrderId)
        self.order_strategies[ticket.OrderId] = strategy

    def OnOrderEvent(self, order_event):
        strategy = self.order_strategies.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.FillQuantity != 0:
            self.lots[strategy] += int(order_event.FillQuantity)

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            self.pending_orders[strategy].discard(order_event.OrderId)
            del self.order_strategies[order_event.OrderId]

