class ParallelSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.previous_closes = {}
        self.previous_spy_relation = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if symbol not in data.bars:
                continue

            bar = data.bars[symbol]
            bars[ticker] = bar

            if ticker == "SPY":
                self.spy_sma.update(bar.end_time, bar.close)
            elif ticker == "AAPL":
                previous_close = self.previous_closes.get(symbol)
                if previous_close is not None:
                    if bar.close < previous_close:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0
                self.aapl_rsi.update(bar.end_time, bar.close)

            self.previous_closes[symbol] = bar.close

        if len(bars) != len(self.symbols):
            self._record_spy_relation(bars)
            return

        spy_bar = bars["SPY"]
        aapl_bar = bars["AAPL"]

        current_spy_relation = None
        if self.spy_sma.is_ready:
            current_spy_relation = spy_bar.close - self.spy_sma.current.value

        spy_crossed_up = (
            self.previous_spy_relation is not None
            and current_spy_relation is not None
            and self.previous_spy_relation <= 0
            and current_spy_relation > 0
        )
        spy_crossed_down = (
            self.previous_spy_relation is not None
            and current_spy_relation is not None
            and self.previous_spy_relation >= 0
            and current_spy_relation < 0
        )

        # Every strategy evaluates its sell before any strategy evaluates a buy.
        if self.spy_lot > 0 and spy_crossed_down:
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and self.aapl_rsi.is_ready
            and self.aapl_rsi.current.value > 60
        ):
            self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crossed_up:
            quantity = floor(0.40 * self.portfolio.total_portfolio_value / spy_bar.close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if (
            self.aapl_lot == 0
            and self.aapl_rsi.is_ready
            and self.aapl_red_streak >= 3
            and self.portfolio.cash >= 20_000
        ):
            quantity = floor(20_000 / aapl_bar.close)
            if quantity > 0:
                self.market_order(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

        self.previous_spy_relation = current_spy_relation

    def _record_spy_relation(self, bars):
        if "SPY" in bars and self.spy_sma.is_ready:
            self.previous_spy_relation = (
                bars["SPY"].close - self.spy_sma.current.value
            )

