class ParallelDailyStrategiesAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            security = self.add_equity(
                ticker, Resolution.DAILY, fill_forward=False
            )
            self.symbols[ticker] = security.symbol

        self.spy_closes = deque(maxlen=100)
        self.previous_spy_side = None

        self.previous_closes = {}
        self.red_streaks = {ticker: 0 for ticker in self.tickers}

        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.WILDERS
        )

        # These quantities are the private lots belonging to the two strategies.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # State is updated whenever a ticker has a genuine bar, even when another
        # ticker is absent and today's trading rules consequently cannot run.
        previous_spy_side = self.previous_spy_side
        spy_side = None
        if "SPY" in bars:
            spy_close = bars["SPY"].close
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 100:
                spy_sma = sum(self.spy_closes) / 100
                if spy_close > spy_sma:
                    spy_side = 1
                elif spy_close < spy_sma:
                    spy_side = -1
                else:
                    spy_side = 0
                self.previous_spy_side = spy_side

        for ticker, bar in bars.items():
            close = bar.close
            if ticker in self.previous_closes:
                if close < self.previous_closes[ticker]:
                    self.red_streaks[ticker] += 1
                else:
                    self.red_streaks[ticker] = 0
            self.previous_closes[ticker] = close

        if "AAPL" in bars:
            self.aapl_rsi.update(self.time, bars["AAPL"].close)

        if len(bars) != len(self.tickers):
            return

        spy_ready = len(self.spy_closes) == 100 and previous_spy_side is not None
        rsi_ready = self.aapl_rsi.is_ready

        upward_cross = (
            spy_ready and previous_spy_side <= 0 and spy_side is not None and spy_side > 0
        )
        downward_cross = (
            spy_ready and previous_spy_side >= 0 and spy_side is not None and spy_side < 0
        )

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and downward_cross:
            self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if (
            self.strategy_b_shares > 0
            and rsi_ready
            and self.aapl_rsi.current.value > 60
        ):
            self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and upward_cross:
            shares = floor(
                0.40 * self.portfolio.total_portfolio_value / bars["SPY"].close
            )
            if shares > 0:
                self.market_order(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

        if (
            self.strategy_b_shares == 0
            and rsi_ready
            and self.red_streaks["AAPL"] >= 3
            and self.portfolio.cash >= 20_000
        ):
            shares = floor(20_000 / bars["AAPL"].close)
            if shares > 0:
                self.market_order(self.symbols["AAPL"], shares)
                self.strategy_b_shares = shares

from AlgorithmImports import *
from collections import deque
from math import floor


class ParallelSpyAaplAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.closes = {
            ticker: deque(maxlen=101) for ticker in self.symbols
        }
        self.red_streak = {ticker: 0 for ticker in self.symbols}

        self.rsi_previous_close = None
        self.rsi_seed_gains = []
        self.rsi_seed_losses = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.spy_up_cross = False
        self.spy_down_cross = False
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities continue to consume each ticker's available
        # trading bars even when another subscribed ticker is absent.
        for ticker, bar in bars.items():
            self._update_close_state(ticker, float(bar.Close))

        # A missing subscribed bar suppresses every strategy rule for the day.
        if len(bars) != len(self.symbols):
            return

        spy_ready = len(self.closes["SPY"]) == 101
        rsi_ready = self.aapl_rsi is not None

        # All sells are evaluated before either independent slot may buy.
        if self.spy_lot > 0 and spy_ready and self.spy_down_cross:
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and rsi_ready and self.aapl_rsi > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_ready and self.spy_up_cross:
            close = float(bars["SPY"].Close)
            quantity = floor((0.40 * float(self.Portfolio.TotalPortfolioValue)) / close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and rsi_ready and self.red_streak["AAPL"] >= 3:
            cash_to_invest = 20_000
            if float(self.Portfolio.Cash) >= cash_to_invest:
                quantity = floor(cash_to_invest / float(bars["AAPL"].Close))
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

    def _update_close_state(self, ticker, close):
        history = self.closes[ticker]
        previous_close = history[-1] if history else None

        if previous_close is None or close >= previous_close:
            self.red_streak[ticker] = 0
        else:
            self.red_streak[ticker] += 1

        history.append(close)

        if ticker == "SPY":
            self.spy_up_cross = False
            self.spy_down_cross = False
            if len(history) == 101:
                values = list(history)
                previous_sma = sum(values[:100]) / 100.0
                current_sma = sum(values[1:]) / 100.0
                previous_relation = values[99] - previous_sma
                current_relation = values[100] - current_sma
                self.spy_up_cross = previous_relation <= 0 and current_relation > 0
                self.spy_down_cross = previous_relation >= 0 and current_relation < 0

        if ticker == "AAPL":
            self._update_aapl_rsi(close)

    def _update_aapl_rsi(self, close):
        if self.rsi_previous_close is None:
            self.rsi_previous_close = close
            return

        change = close - self.rsi_previous_close
        self.rsi_previous_close = close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.rsi_average_gain is None:
            self.rsi_seed_gains.append(gain)
            self.rsi_seed_losses.append(loss)
            if len(self.rsi_seed_gains) < 14:
                return
            self.rsi_average_gain = sum(self.rsi_seed_gains) / 14.0
            self.rsi_average_loss = sum(self.rsi_seed_losses) / 14.0
        else:
            self.rsi_average_gain = (13.0 * self.rsi_average_gain + gain) / 14.0
            self.rsi_average_loss = (13.0 * self.rsi_average_loss + loss) / 14.0

        if self.rsi_average_loss == 0:
            self.aapl_rsi = 100.0 if self.rsi_average_gain > 0 else 50.0
        else:
            relative_strength = self.rsi_average_gain / self.rsi_average_loss
            self.aapl_rsi = 100.0 - (100.0 / (1.0 + relative_strength))
